// Run with: npm test   (node's built-in runner; Node strips the TS types)
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import JSZip from "jszip";
import { sanitizePptx, findDanglingOverrides } from "../src/components/shared/pptx-sanitize.ts";

// Generated by PptxGenJS 3.12 with two slides: [Content_Types].xml declares
// ppt/slideMasters/slideMaster2.xml, which is not in the package.
const FIXTURE = new URL("./fixtures/pptxgenjs-missing-slide-master.pptx", import.meta.url);
const MISSING = "ppt/slideMasters/slideMaster2.xml";

async function load(buffer) {
  const zip = await JSZip.loadAsync(buffer);
  const xml = await zip.file("[Content_Types].xml").async("string");
  return { zip, xml, dangling: findDanglingOverrides(xml, (p) => zip.file(p) !== null) };
}

async function fixtureBuffer() {
  const bytes = await readFile(FIXTURE);
  return bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);
}

test("fixture really has the dangling slideMaster override", async () => {
  const { dangling } = await load(await fixtureBuffer());
  assert.deepEqual(dangling, [MISSING]);
});

test("sanitizePptx removes only overrides whose part is missing", async () => {
  const before = await load(await fixtureBuffer());
  const after = await load(await sanitizePptx(await fixtureBuffer()));

  assert.deepEqual(after.dangling, []);
  assert.ok(!after.xml.includes(MISSING));
  const count = (xml) => (xml.match(/<Override\b/g) ?? []).length;
  assert.equal(count(after.xml), count(before.xml) - 1);
  for (const part of ["ppt/slideMasters/slideMaster1.xml", "ppt/slides/slide1.xml", "ppt/slides/slide2.xml"]) {
    assert.ok(after.xml.includes(`/${part}`), `${part} override kept`);
    assert.ok(after.zip.file(part), `${part} still in the package`);
  }
});

test("a clean package is returned untouched", async () => {
  const cleaned = await sanitizePptx(await fixtureBuffer());
  assert.equal(await sanitizePptx(cleaned), cleaned);
});

test("a non-zip buffer is passed through", async () => {
  const junk = new TextEncoder().encode("not a zip").buffer;
  assert.equal(await sanitizePptx(junk), junk);
});
